  RetentionRule(category: 'veg_other', groups: 'G', include: r'(broccoli|blumenkohl|romanesco|rosenkohl|rotkohl|weißkohl|wirsing|spitzkohl|chinakohl|pak choi|spargel|porree|zucchini|kürbis|aubergine|paprika|zuckermais|bohne grün|wachsbohne|dicke bohne|zuckererbse|erbse grün|fenchel|okra|artischocke|chayote|speisezwiebel|schalotte|perlzwiebel|frühlingszwiebel|lauchzwiebel)', exclude: r'saft|konserve|getrocknet|pulver|tiefgefroren|mischung|suppe|pfefferschote|sauerkraut|kernöl|reif$|schnittlauch'),
